import{_ as a,o,c as r,a2 as i}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Progresión del personaje","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/characters/progression.md","filePath":"es/guide/characters/progression.md"}'),s={name:"es/guide/characters/progression.md"};function n(t,e,d,c,l,p){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="character-progression" tabindex="-1">Progresión del personaje <a class="header-anchor" href="#character-progression" aria-label="Enlace permanente a &quot;Progresión del personaje&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto.</strong> Son cambios previstos, no reglas confirmadas del juego disponible. <strong>Implementación/disponibilidad:</strong> no acreditada para este rediseño. <strong>Verificación:</strong> solo revisión documental. <strong>Revisado:</strong> 2026-10-08 frente a la <a href="/Syrolands-Public/es/game-design/characters/progression.html">especificación completa</a>.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Los personajes útiles desde el inicio crecen mediante habilidad, conocimiento y dominio del jugador.</li><li>El presupuesto propuesto ronda los 700 puntos de habilidad en total, con 100 como máximo normal.</li><li>La especialización, la reputación y el descubrimiento ofrecen metas más allá de maximizar habilidades.</li></ul><h2 id="useful-from-the-first-day" tabindex="-1">Útil desde el primer día <a class="header-anchor" href="#useful-from-the-first-day" aria-label="Enlace permanente a &quot;Útil desde el primer día&quot;">​</a></h2><p>La experiencia deseada es sencilla: un personaje inexperto ya debe ser funcional. Alrededor de habilidad 20 deberías poder participar en una disciplina. El entrenamiento posterior debe ampliar lo que puedes hacer, tu consistencia y los desafíos que puedes afrontar.</p><h2 id="three-ways-to-grow" tabindex="-1">Tres formas de crecer <a class="header-anchor" href="#three-ways-to-grow" aria-label="Enlace permanente a &quot;Tres formas de crecer&quot;">​</a></h2><p>La <strong>habilidad del personaje</strong> proporciona capacidad. El <strong>conocimiento</strong> abre posibilidades e información. El <strong>dominio del jugador</strong> condiciona la ejecución. Dos personajes con el mismo entrenamiento pueden conocer técnicas distintas, y dos jugadores con la misma configuración pueden rendir de manera diferente.</p><p>Se propone que la habilidad normal llegue hasta 100; no se planea una progresión ordinaria a 120. Llegar a 100 debe representar dominio técnico, no desbloquear por fin el juego real ni completar todos los descubrimientos.</p><h2 id="a-build-with-tradeoffs" tabindex="-1">Una configuración con compromisos <a class="header-anchor" href="#a-build-with-tradeoffs" aria-label="Enlace permanente a &quot;Una configuración con compromisos&quot;">​</a></h2><p>El presupuesto aproximado de 700 puntos debe permitir especializaciones principales, habilidades de apoyo e inversiones menores de utilidad. Ni siete habilidades a 100 ni catorce a 50 deben ser automáticamente la mejor opción. La experiencia profunda importa, pero una inversión menor también debe ser útil.</p><h2 id="more-than-one-endgame" tabindex="-1">Más de una meta a largo plazo <a class="header-anchor" href="#more-than-one-endgame" aria-label="Enlace permanente a &quot;Más de una meta a largo plazo&quot;">​</a></h2><p>Podrías ser conocido como duelista, cazador, maestro fabricante de arcos, cocinero, erudito, comerciante u organizador de una comunidad. Son aspiraciones posibles, no una promesa de que existan todos los sistemas necesarios. El conocimiento, la reputación, la participación social y el dominio humano pueden importar sin que cada camino exija llegar a 100.</p><p><a href="/Syrolands-Public/es/guide/characters/skills.html">Habilidades y maestros</a> · <a href="/Syrolands-Public/es/guide/characters/techniques.html">Técnicas</a> · <a href="/Syrolands-Public/es/guide/characters/character-creation.html">Trasfondos</a> · <a href="/Syrolands-Public/es/guide/characters/stats.html">Atributos</a> · <a href="/Syrolands-Public/es/guide/professions/overview.html">Profesiones</a></p>',14)])])}const h=a(s,[["render",n]]);export{m as __pageData,h as default};
